use vstd::prelude::*;

verus! {
    fn remove_kth_element(list: &Vec<i32>, k: usize) -> (new_list: Vec<i32>)
        requires
            1 <= k < list.len(),
        ensures
            new_list.len() == list.len() - 1,
            forall |i: usize| (0 <= i < k - 1 ==> new_list[i] == list[i]) &&
            forall |i: usize| (k - 1 <= i < new_list.len() ==> new_list[i] == list[i + 1]),
    {
        let n = list.len();
        let mut new_list: Vec<i32> = Vec::new();
        
        // Fill the new list with elements from the original list
        let mut i = 0;
        while i < n
            invariant
                new_list.len() == i,
                i <= n,
                new_list.len() <= n - 1,
                forall |j: usize| (0 <= j < new_list.len() ==> new_list[j] == list[j + (if j < k - 1 { 0 } else { 1 })]),
            decreases n - i,
        {
            if i == k - 1 {
                // Skip the k-th element (1-based index)
                i = i + 1;
                continue;
            }
            new_list.push(list[i]);
            i = i + 1;
        }
        
        new_list
    }
}
